test("day 31 clamps in short months and the next month returns to 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});
test("December start crosses into January and leap-year February ends on the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});
test("a day that exists in every month is never adjusted", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});
test("smallest stated count is one payment and returns a single date", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-06-15", count: 1 }), ["2026-07-15"]);
});
test("first day of a month stays the 1st", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-01", count: 2 }), ["2026-02-01", "2026-03-01"]);
});
test("non-leap February keeps day 28 because it exists", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-28", count: 1 }), ["2026-02-28"]);
});
test("non-leap February clamps one day past the end to the 28th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-29", count: 1 }), ["2026-02-28"]);
});
test("leap February keeps day 28 one below the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-28", count: 1 }), ["2024-02-28"]);
});
test("leap day itself exists so day 29 is kept", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-29", count: 1 }), ["2024-02-29"]);
});
test("leap February clamps one day past the 29th to the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-30", count: 1 }), ["2024-02-29"]);
});
test("day 30 exists in a 30-day April", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-03-30", count: 1 }), ["2026-04-30"]);
});
test("day 31 clamps in April and May returns to 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-03-31", count: 2 }), ["2026-04-30", "2026-05-31"]);
});
test("shortened February in the middle does not change March back from 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2025-12-31", count: 4 }), ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30"]);
});
test("an earlier clamp does not change the original day for a later shortened month", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 4 }), ["2026-02-28", "2026-03-31", "2026-04-30", "2026-05-31"]);
});
test("September clamps 31 to 30 and October returns to 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-08-31", count: 2 }), ["2026-09-30", "2026-10-31"]);
});
test("start on a leap day clamps the next non-leap February then returns to 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-02-29", count: 13 }), ["2028-03-29", "2028-04-29", "2028-05-29", "2028-06-29", "2028-07-29", "2028-08-29", "2028-09-29", "2028-10-29", "2028-11-29", "2028-12-29", "2029-01-29", "2029-02-28", "2029-03-29"]);
});
